/**
 * @file Standard glob patterns for paths ignored by linting, formatting, and spell-checking tools.
 */

/**
 * Core build junk, autogenerated changelogs, and temporary cache files.
 */
export const core = [
  '**/*LICENSE*',
  '**/CHANGELOG.md',
  '**/*.log',
  '**/*.min.*',
  '**/*.map',
  '**/*.tsbuildinfo',
  '**/*.d.ts',
  '**/.cache/**',
  '**/.temp/**',
  '**/.tmp/**',
  '**/.DS_Store',
] as const;

/**
 * Node.js, JavaScript, and TypeScript build outputs and caches.
 */
export const node = [
  '**/node_modules/**',
  '**/dist/**',
  '**/build/**',
  '**/out/**',
  '**/out-tsc/**',
  '**/coverage/**',
  '**/.next/**',
  '**/.nuxt/**',
  '**/.svelte-kit/**',
  '**/.turbo/**',
  '**/.pnpm/**',
  '**/.pnpm-store/**',
  '**/.npm/**',
  '**/.yarn/**',
  '**/.pnp/**',
  '**/.parcel-cache/**',
  '**/.vite/**',
  '**/.rollup.cache/**',
  '**/.vercel/**',
  '**/.netlify/**',
  '**/.wrangler/**',
  '**/.output/**',
  '**/.docusaurus/**',
  '**/.storybook-out/**',
  '**/storybook-static/**',
] as const;

/**
 * Package manager lock files across npm, pnpm, yarn, and bun.
 */
export const lockFiles = [
  '**/package-lock.json',
  '**/pnpm-lock.yaml',
  '**/yarn.lock',
  '**/bun.lockb',
  '**/bun.lock',
] as const;

/**
 * Rust toolchain build outputs and cargo lock files.
 */
export const rust = ['**/target/**', '**/.cargo/**', '**/Cargo.lock'] as const;

/**
 * Go toolchain build outputs, vendor directories, and dependency files.
 */
export const go = [
  '**/go.sum',
  '**/go.work',
  '**/go.work.sum',
  '**/vendor/**',
  '**/.gopath/**',
  '**/.cache/go-build/**',
] as const;

/**
 * Python toolchain caches, bytecode, and virtual environments.
 */
export const python = [
  '**/__pycache__/**',
  '**/*.pyc',
  '**/*.pyo',
  '**/.mypy_cache/**',
  '**/.pytest_cache/**',
  '**/.tox/**',
  '**/.ruff_cache/**',
  '**/.venv/**',
  '**/venv/**',
  '**/env/**',
  '**/.ipynb_checkpoints/**',
] as const;

/**
 * AI coding agents, assistant configurations, and LLM instruction files.
 */
export const aiAgents = [
  '**/.agents/**',
  '**/.claude/**',
  '**/.cursor/**',
  '**/.gemini/**',
  '**/.windsurf/**',
  '**/.roo/**',
  '**/.aider*',
  '**/.cursorrules',
  '**/.cursorignore',
  '**/.clinerules',
  '**/.roorules',
  '**/AGENTS.md',
  '**/CLAUDE.md',
  '**/GEMINI.md',
  '**/.github/copilot-instructions.md',
  '**/.github/instructions/**',
] as const;

/**
 * Miscellaneous developer toolchains, IDEs, and system dotfiles.
 */
export const toolchains = [
  '**/.git/**',
  '**/.svn/**',
  '**/.hg/**',
  '**/.idea/**',
  '**/.vscode/**',
  '**/.editorconfig',
  '**/.eslintcache',
  '**/.babelrc',
  '**/.prettier*',
  '**/.nx/**',
  '**/.cspell/**',
  '**/.history/**',
  '**/.sass-cache/**',
  '**/.gradle/**',
  '**/.terraform/**',
  '**/.docker/**',
  '**/.kube/**',
  '**/.devcontainer/**',
  '**/.direnv/**',
  '**/.astro/**',
  '**/.codacy/**',
  '**/.changeset/**',
] as const;

/**
 * Windows and WSL specific metadata and system files.
 */
export const windows = [
  '**/*:Zone.Identifier',
  '**/*:Zone.Identifier*',
  '**/Thumbs.db',
  '**/desktop.ini',
  '**/$RECYCLE.BIN/**',
  '**/System Volume Information/**',
  '**/pagefile.sys',
  '**/swapfile.sys',
  '**/hiberfil.sys',
] as const;

/**
 * Specific project artifacts and template files.
 */
export const misc = ['**/connect.lock', '**/*.hbs', '**/*.mustache'] as const;

/**
 * Combined list of all standard ignore glob patterns.
 */
export const all: readonly string[] = [
  ...core,
  ...node,
  ...lockFiles,
  ...rust,
  ...go,
  ...python,
  ...aiAgents,
  ...toolchains,
  ...windows,
  ...misc,
];

/**
 * Uppercase alias for {@link core}.
 */
export const CORE_IGNORE_PATHS: typeof core = core;

/**
 * Uppercase alias for {@link node}.
 */
export const NODE_IGNORE_PATHS: typeof node = node;

/**
 * Uppercase alias for {@link lockFiles}.
 */
export const LOCK_FILES_IGNORE_PATHS: typeof lockFiles = lockFiles;

/**
 * Uppercase alias for {@link rust}.
 */
export const RUST_IGNORE_PATHS: typeof rust = rust;

/**
 * Uppercase alias for {@link go}.
 */
export const GO_IGNORE_PATHS: typeof go = go;

/**
 * Uppercase alias for {@link python}.
 */
export const PYTHON_IGNORE_PATHS: typeof python = python;

/**
 * Uppercase alias for {@link aiAgents}.
 */
export const AI_AGENTS_IGNORE_PATHS: typeof aiAgents = aiAgents;

/**
 * Uppercase alias for {@link toolchains}.
 */
export const TOOLCHAINS_IGNORE_PATHS: typeof toolchains = toolchains;

/**
 * Uppercase alias for {@link windows}.
 */
export const WINDOWS_IGNORE_PATHS: typeof windows = windows;

/**
 * Uppercase alias for {@link misc}.
 */
export const MISC_IGNORE_PATHS: typeof misc = misc;

/**
 * Uppercase alias for {@link all}.
 */
export const ALL_IGNORE_PATHS: readonly string[] = all;

/**
 * Mutable copy of {@link all}, for tools that expect a `string[]`.
 */
export const ignorePaths: string[] = [...all];

/**
 * Type of the unified `ignores` dictionary.
 */
export interface IgnoresDictionary {
  /**
   * AI coding agents, assistant configurations, and LLM instruction files.
   */
  readonly aiAgents: typeof aiAgents;
  /**
   * Combined list of all standard ignore glob patterns.
   */
  readonly all: typeof all;
  /**
   * Core build junk, autogenerated changelogs, and temporary cache files.
   */
  readonly core: typeof core;
  /**
   * Go toolchain build outputs, vendor directories, and dependency files.
   */
  readonly go: typeof go;
  /**
   * Package manager lock files across npm, pnpm, yarn, and bun.
   */
  readonly lockFiles: typeof lockFiles;
  /**
   * Specific project artifacts and template files.
   */
  readonly misc: typeof misc;
  /**
   * Node.js, JavaScript, and TypeScript build outputs and caches.
   */
  readonly node: typeof node;
  /**
   * Python toolchain caches, bytecode, and virtual environments.
   */
  readonly python: typeof python;
  /**
   * Rust toolchain build outputs and cargo lock files.
   */
  readonly rust: typeof rust;
  /**
   * Miscellaneous developer toolchains, IDEs, and system dotfiles.
   */
  readonly toolchains: typeof toolchains;
  /**
   * Windows and WSL specific metadata and system files.
   */
  readonly windows: typeof windows;
}

/**
 * Dictionary of all ignore recipe categories and complete collections.
 */
export const ignores: IgnoresDictionary = {
  aiAgents: aiAgents,
  all: all,
  core: core,
  go: go,
  lockFiles: lockFiles,
  misc: misc,
  node: node,
  python: python,
  rust: rust,
  toolchains: toolchains,
  windows: windows,
};

/**
 * Valid keys in the `ignores` dictionary.
 */
export type IgnoreRecipeKey = keyof IgnoresDictionary;

/**
 * Default export of the unified ignores dictionary.
 */
export default ignores;
